import os

import httpx
import typer
from rich.console import Console

from mc_cli.client import error_message, request, send
from mc_cli.token_store import delete_token, save_token
from mc_shared import Health, Me, Token

API_URL = os.environ.get("MC_API_URL", "http://localhost:8000")

app = typer.Typer(no_args_is_help=True)
console = Console()


@app.callback()
def main() -> None:
    """Mission Control CLI."""


@app.command()
def health() -> None:
    """Check that the API and the database are up."""
    try:
        response = httpx.get(f"{API_URL}/health")
        response.raise_for_status()
    except httpx.HTTPError as exc:
        console.print(f"[red]API at {API_URL} is not reachable:[/red] {exc}")
        raise typer.Exit(1)
    result = Health.model_validate(response.json())
    console.print(f"[green]API {result.status}[/green], database {result.db} ({API_URL})")


def show(me: Me) -> str:
    return f"{me.username} ({me.display_name}), role {me.role}, org {me.org_name}"


@app.command()
def login(user: str = typer.Option(..., "--user", help="Username to log in as.")) -> None:
    """Log in and store the token."""
    response = send("POST", "/auth/login", json={"username": user})
    if response.status_code == 401:
        console.print(f"Login failed: unknown user '{user}'", markup=False)
        raise typer.Exit(1)
    if response.status_code >= 400:
        console.print(error_message(response), markup=False)
        raise typer.Exit(1)
    save_token(Token.model_validate(response.json()).access_token)
    me = Me.model_validate(request("GET", "/me").json())
    console.print(f"Logged in as {show(me)}", markup=False)


@app.command()
def whoami() -> None:
    """Show the logged-in user."""
    console.print(show(Me.model_validate(request("GET", "/me").json())), markup=False)


@app.command()
def logout() -> None:
    """Delete the stored token."""
    console.print("Logged out." if delete_token() else "Not logged in.")

#!/usr/bin/env bash
# Checks for the verify tiers (D4). Usage: check.sh fast|full
# Prints only failures, each line marked ERROR. Exits non-zero if a check fails.
set -u
cd "$(dirname "$0")/.." || exit 1
failed=0

# Runs one check: run <name> '<command>'. On failure, prints the last 40 lines (a build log can have hundreds).
# Give one command for each call. A chain prints the success output of the earlier commands when a later one fails.
run() {
  local name=$1 out
  shift
  out=$(bash -c "$*" 2>&1) || { tail -n 40 <<<"$out" | sed "s/^/ERROR: $name: /"; failed=1; }
}

# Format check, lint, typecheck and unit tests. Example: run api-lint 'cd api && uv run ruff check .'
fast() {
  run format 'uv run ruff format --check -q .'
  run lint 'uv run ruff check -q .'
  run tests 'uv run pytest -q -m "not e2e"'
}

# Build, all other tests and e2e. Give each e2e step its own call: start, smoke, browser tests, stop.
full() {
  run e2e 'uv run pytest -q -m e2e'
}

case "${1:-}" in
  fast) fast ;;
  full) fast; full ;;
  *) echo "ERROR: Unknown tier. Use: check.sh fast|full" >&2; exit 1 ;;
esac
exit "$failed"

